const raw = $input.first().json;
let body = (raw && typeof raw === 'object' && raw.body !== undefined && raw.body !== null) ? raw.body : raw;
if (typeof body === 'string') {
  try {
    body = JSON.parse(body);
  } catch (e) {
    throw new Error('Malformed event body JSON');
  }
}
if (!body || typeof body !== 'object' || Array.isArray(body)) {
  throw new Error('Invalid event payload');
}
const wrapperKeys = new Set(['headers', 'params', 'query', 'webhookUrl', 'executionMode']);
const eventKeys = Object.keys(body).filter(k => !wrapperKeys.has(k)).sort();
const expectedKeys = ['case_id', 'event_idempotency_key', 'event_type', 'resolution_type'];
if (eventKeys.join(',') !== expectedKeys.join(',')) throw new Error('Unexpected event fields');
if (body.event_type !== 'case.resolution_ready') throw new Error('Unsupported event type');
if (typeof body.case_id !== 'string' || !/^[A-Za-z0-9_-]{1,80}$/.test(body.case_id)) throw new Error('Invalid case id');
if (body.event_idempotency_key !== `resolveai-case-${body.case_id}`) throw new Error('Invalid idempotency key');
const allowedTypes = ['refund', 'replacement', 'return', 'explanation', 'escalation'];
if (!allowedTypes.includes(body.resolution_type)) throw new Error('Unsupported resolution type');
return [{ json: { status: 'completed', event_idempotency_key: body.event_idempotency_key, demo_result: 'simulated_notification' } }];
